import base64
from PIL import ImageTk

# Dekoder base64-strenger til ikoner
_ROTATE_BASE64 = (
    ""
)
_KEYBOARD_BASE64 = (
    ""
)
_RESTART_BASE64 = (
    ""
)

# Oppretter PhotoImage-objekter for bruk i GUI
img_refresh = ImageTk.PhotoImage(
    data=base64.b64decode(_RESTART_BASE64)
)

img_keyboard = ImageTk.PhotoImage(
    data=base64.b64decode(_KEYBOARD_BASE64)
)

img_rotate = ImageTk.PhotoImage(
    data=base64.b64decode(_ROTATE_BASE64)
)